    return answer(`\u0421\u043E\u0431\u0440\u0430\u043B \u0447\u0435\u0440\u043D\u043E\u0432\u0438\u043A \xAB${r.actions[0].draft.title}\xBB: \u043D\u0430\u0433\u0440\u0430\u0434\u0430 ${r.actions[0].draft.reward} AB, ${r.actions[0].draft.maxParticipants} \u0443\u0447\u0430\u0441\u0442\u043D\u0438\u043A\u043E\u0432, ${r.actions[0].draft.questions.length} \u0432\u043E\u043F\u0440\u043E\u0441\u0430. \u041F\u0440\u043E\u0432\u0435\u0440\u044C \u0444\u043E\u0440\u043C\u0443 \u0438 \u043D\u0430\u0436\u043C\u0438 \xAB\u041E\u043F\u0443\u0431\u043B\u0438\u043A\u043E\u0432\u0430\u0442\u044C\xBB \u2014 \u0431\u0435\u0437 \u0442\u0435\u0431\u044F \u043D\u0438\u0447\u0435\u0433\u043E \u043D\u0435 \u0437\u0430\u043F\u0443\u0441\u0442\u0438\u0442\u0441\u044F.`, r);
